What was thinking was this. The update of which device they belong to does not to be done since that will be handled once they get added to the system. I find this much more readable. (not fully fleshed out the code, so tests fail due to not adjusting the associated device id)

The problem here is that: "{entry.entry_id}_hourly_gas_meter_reading" can exist in 4 series device without any mbus data: See here: https://github.com/ndokter/dsmr_parser/blob/94189b6b63e12554c866bc2964ffb7d5c7e8b2c4/dsmr_parser/telegram_specifications.py#L286

So i'm not sure we should include that...

```python
def rename_old_gas_to_mbus(
    hass: HomeAssistant, entry: ConfigEntry, mbus_device_id: str
) -> None:
    """Rename old gas sensor to mbus variant."""

    adjustments = {
        f"{mbus_device_id}_hourly_gas_meter_reading": mbus_device_id,
        f"{entry.unique_id}_hourly_gas_meter_reading": mbus_device_id,
        f"{entry.unique_id}_belgium_5min_gas_meter_reading": mbus_device_id,
        f"{mbus_device_id}_belgium_5min_gas_meter_reading": mbus_device_id,
    }

    ent_reg = er.async_get(hass)
    entries = er.async_entries_for_config_entry(ent_reg, entry.entry_id)
    for entity in entries:
        if not (new := adjustments.get(entity.unique_id, None)):
            continue

        try:
            ent_reg.async_update_entity(
                entity.entity_id,
                new_unique_id=new,
            )
        except ValueError:
            LOGGER.debug(
                "Skip migration of %s because it already exists",
                entity.entity_id,
            )
        else:
            LOGGER.debug(
                "Migrated entity %s from unique id %s to %s",
                entity.entity_id,
                entity.unique_id,
                mbus_device_id,
                )


def cleanup_empty_devices(hass: HomeAssistant, entry: ConfigEntry):
    """Cleanup old devices."""
    dev_reg = dr.async_get(hass)
    ent_reg = er.async_get(hass)
    devices = dr.async_entries_for_config_entry(dev_reg, entry.entry_id)
    for device in devices:
        dev_entities = er.async_entries_for_device(
            ent_reg, device.id, include_disabled_entities=True
        )
        if not dev_entities:
            dev_reg.async_remove_device(device.id)
```

